<?php
require_once __DIR__ . '/bootstrap.php';
require_roles(['SUPER_ADMIN', 'MANAGER', 'FIRM']);
try { $application = $lending->application((int) ($_GET['id'] ?? 0)); }
catch (OutOfBoundsException $error) { http_response_code(404); exit(t('Application not found.')); }
$title = t('Application #') . $application['application_id'];
require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow"><?= e(t('Application #')) ?><?= e($application['application_id']) ?></span><h1><?= e($application['full_name']) ?></h1><p><?= e($application['product_name']) ?> <?= e(t('· Submitted')) ?> <?= e(format_date($application['submission_date'], true)) ?></p></div><?= status_badge($application['status']) ?></div>
<div class="portal-grid"><section class="card"><h2><?= e(t('Application details')) ?></h2><dl class="detail-list detail-columns"><?php foreach (['amount_requested_rwf'=>t('Requested amount'),'term_months'=>t('Term (months)'),'purpose'=>t('Purpose'),'monthly_income_rwf'=>t('Monthly income'),'phone_number'=>t('Phone'),'kyc_status'=>t('Customer verification')] as $key=>$label): ?><div><dt><?= e(t($label)) ?></dt><dd class="preserve-lines"><?= e(str_ends_with($key, '_rwf') ? money($application[$key]) : ($key === 'kyc_status' ? status_label($application[$key]) : $application[$key])) ?></dd></div><?php endforeach; ?><div><dt><?= e(t('Interest rate')) ?></dt><dd><?= e(format_number($application['interest_rate_pct'], 2)) ?><?= e(t('% flat, applied once')) ?></dd></div><div><dt><?= e(t('Collateral document required')) ?></dt><dd><?= $application['requires_collateral'] ? t('Yes') : t('No') ?></dd></div></dl><div class="button-group"><a class="button secondary" href="<?= e(app_url('portal/documents.php?customer_id=' . $application['customer_id'])) ?>"><?= e(t('Review customer documents ↗')) ?></a><?php if ($application['loan_id']): ?><a class="button" href="<?= e(app_url('workspace/loan.php?id=' . $application['loan_id'])) ?>"><?= e(t('View issued loan →')) ?></a><?php endif; ?></div><?php if ($application['manager_notes']): ?><div class="notice"><strong><?= e(t('Decision / internal notes')) ?></strong><p class="preserve-lines"><?= e($application['manager_notes']) ?></p></div><?php endif; ?></section>
<aside class="card"><h2><?= e(t('Manager decision')) ?></h2><?php if (in_array($user['role_name'], ['MANAGER','SUPER_ADMIN'], true) && in_array($application['status'], ['SUBMITTED','UNDER_REVIEW'], true)): ?><form method="POST" action="<?= e(app_url('workspace/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="application"><input type="hidden" name="id" value="<?= e($application['application_id']) ?>"><div class="field"><label for="amount"><?= e(t('Approved principal (RWF)')) ?></label><input id="amount" type="number" name="amount" min="0.01" max="<?= e($application['amount_requested_rwf']) ?>" step="0.01" value="<?= e($application['amount_requested_rwf']) ?>"></div><div class="field"><label for="notes"><?= e(t('Decision notes')) ?></label><textarea id="notes" name="notes" maxlength="1000" placeholder="<?= e(t('A reason is required to reject')) ?>"></textarea></div><p class="help"><?= e(t('Approval creates a loan using the product’s flat interest rate. An accountant then records the disbursement.')) ?></p><div class="decision-buttons"><button class="button" name="decision" value="APPROVED"><?= e(t('Approve loan')) ?></button><button class="button secondary" name="decision" value="UNDER_REVIEW"><?= e(t('Mark under review')) ?></button><button class="button danger" name="decision" value="REJECTED"><?= e(t('Reject application')) ?></button></div></form><?php else: ?><p class="muted"><?= $user['role_name'] === 'FIRM' ? t('Your manager reviews applications and makes lending decisions.') : t('This application has a final decision.') ?></p><?php endif; ?></aside></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
